using System.Globalization;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;

namespace WoWCrucible.Core;

/// <summary>
/// Generates matching C++ and Rust wire codecs from one protocol definition. Output is deterministic:
/// the same definition and generator version give the same bytes, with no time or machine in them.
/// It is not a service or a build dependency: consumers check the generated files in as plain source.
/// </summary>
public static class WireProtocolGenerator
{
    /// <summary>The definition grammar this generator reads.</summary>
    public const int SchemaFormat = 1;

    /// <summary>A definition pins this; a generator change that alters output bumps it.</summary>
    public const int GeneratorVersion = 1;

    public const string BodyHashMarker = "// body-sha256: ";

    public static WireProtocol Parse(string definitionText) => WireProtocolParser.Parse(definitionText);

    /// <summary>SHA-256 of the text with CRLF read as LF, so a checkout's line endings do not change it.</summary>
    public static string TextHash(string text) =>
        Convert.ToHexStringLower(SHA256.HashData(Encoding.UTF8.GetBytes(text.Replace("\r\n", "\n"))));

    /// <summary>The generated files for a parsed definition, keyed by their role.</summary>
    public static WireGeneratedSet Generate(WireProtocol protocol, string definitionText, string definitionFileName)
    {
        var hash = TextHash(definitionText);
        return new WireGeneratedSet(
            Seal(WireCppEmitter.Codec(protocol), $"protocol: {protocol.Version}", hash, definitionFileName),
            Seal(WireCppEmitter.Dump(protocol), $"protocol: {protocol.Version}", hash, definitionFileName),
            Seal(WireRustEmitter.Emit(protocol), $"protocol: {protocol.Version}", hash, definitionFileName));
    }

    /// <summary>
    /// The header's stamp is part of the file, and the body hash under it lets a check with no generator
    /// (Python on the server, a Rust test on the client) see a hand edit or a stale definition.
    /// </summary>
    internal static string Seal(string body, string version, string definitionHash, string definitionFileName)
    {
        var header = new StringBuilder();
        header.Append("// GENERATED by `wowcrucible protocol gen`. DO NOT EDIT: change ").Append(definitionFileName).Append(" and regenerate.\n");
        header.Append("// definition-sha256: ").Append(definitionHash).Append('\n');
        header.Append(CultureInfo.InvariantCulture, $"// schema-format: {SchemaFormat}, generator: {GeneratorVersion}, {version}\n");
        header.Append(BodyHashMarker).Append(TextHash(body)).Append('\n');
        return header + body;
    }
}

public sealed record WireGeneratedSet(string CppCodec, string CppDump, string Rust);

public sealed record WireConstant(string Name, string Type, ulong Value, bool Hex, string Doc);

public abstract record WireType;
public sealed record WirePrimitive(string Name) : WireType
{
    public int Size => Name switch { "u8" => 1, "u16" => 2, "u32" => 4, "u64" => 8, _ => throw new InvalidOperationException(Name) };
}
public sealed record WireBool : WireType;
public sealed record WireBytes(int Length) : WireType;
public sealed record WireList(WirePrimitive Count, string? MaxConstant, WireType Item, int? StrictMin, string? StrictAscending, bool StrictUnique, IReadOnlyList<string> ItemStrict) : WireType;
public sealed record WireStructRef(string Name) : WireType;
public sealed record WireOptional(string Flag, WireType Inner) : WireType;
public sealed record WireTagged(string Name) : WireType;

/// <summary>Exactly one of Type, Const with Type, or Magic describes a field.</summary>
public sealed record WireField(string Name, WireType? Type, string? Const, string? Magic, IReadOnlyList<string> Strict, string Doc)
{
    public bool InValue => Const is null && Magic is null;
}

public sealed record WireStruct(string Name, bool RustTuple, string Doc, IReadOnlyList<WireField> Fields, ushort? Opcode, bool IsMessage, bool Strict, string Direction)
{
    public IEnumerable<WireField> Values => Fields.Where(entry => entry.InValue);
}

public sealed record WireProtocol(
    int SchemaFormat, int GeneratorVersion, string Name, int Version,
    string CppNamespace, string CppHeader, string CppDumpHeader,
    string RustFile, string RustPinDir, string Fixtures,
    int MergedShift, IReadOnlyList<int> MergedSources,
    IReadOnlyList<WireConstant> Constants, IReadOnlyList<WireStruct> Structs)
{
    public WireStruct Find(string name) => Structs.First(item => item.Name == name);
    public IEnumerable<WireStruct> Messages => Structs.Where(item => item.IsMessage);

    public ulong Constant(string name) => name.All(char.IsDigit)
        ? ulong.Parse(name, CultureInfo.InvariantCulture)
        : Constants.First(item => item.Name == name).Value;

    /// <summary>The largest body this type can legally have, for a message's registered size limit.</summary>
    public ulong MaxSize(WireType type) => type switch
    {
        WirePrimitive primitive => (ulong)primitive.Size,
        WireBool => 1,
        WireBytes bytes => (ulong)bytes.Length,
        WireList list => (ulong)list.Count.Size + ListLimit(list) * MaxSize(list.Item),
        WireStructRef reference => MaxSize(Find(reference.Name)),
        WireOptional optional => 1 + MaxSize(optional.Inner),
        WireTagged tagged => MaxSize(Find(tagged.Name)),
        _ => throw new InvalidOperationException()
    };

    public ulong MaxSize(WireStruct item) => item.Fields.Aggregate(0UL, (total, field) => total + field switch
    {
        { Magic: not null } => (ulong)field.Magic.Length,
        _ => MaxSize(field.Type!)
    });

    public ulong ListLimit(WireList list) => list.MaxConstant is { } name
        ? Constant(name)
        : list.Count.Size == 1 ? 255UL : 65535UL;
}

internal static class WireProtocolParser
{
    private static readonly JsonDocumentOptions Options = new() { CommentHandling = JsonCommentHandling.Skip };

    public static WireProtocol Parse(string text)
    {
        using var document = JsonDocument.Parse(text, Options);
        var root = document.RootElement;
        Only(root, "definition", "schema_format", "generator_version", "name", "protocol", "cpp", "rust", "fixtures", "merged_id", "constants", "aliases", "structs", "messages");

        var schemaFormat = Int(root, "schema_format");
        if (schemaFormat != WireProtocolGenerator.SchemaFormat)
            throw new InvalidDataException($"This generator reads schema format {WireProtocolGenerator.SchemaFormat}; the definition is format {schemaFormat}.");
        var generator = Int(root, "generator_version");
        if (generator != WireProtocolGenerator.GeneratorVersion)
            throw new InvalidDataException($"The definition pins generator {generator}; this is generator {WireProtocolGenerator.GeneratorVersion}. Change the pin on purpose, and review the regenerated output.");

        var cpp = root.GetProperty("cpp");
        Only(cpp, "cpp", "namespace", "header", "dump_header");
        var rust = root.GetProperty("rust");
        Only(rust, "rust", "file", "pin_dir");
        var merged = root.GetProperty("merged_id");
        Only(merged, "merged_id", "shift", "sources");

        var constants = root.GetProperty("constants").EnumerateArray().Select(ParseConstant).ToArray();
        Unique(constants.Select(item => item.Name), "constant");

        var aliases = new Dictionary<string, JsonElement>(StringComparer.Ordinal);
        foreach (var alias in root.GetProperty("aliases").EnumerateObject()) aliases.Add(alias.Name, alias.Value);

        var structs = new List<WireStruct>();
        foreach (var element in root.GetProperty("structs").EnumerateArray()) structs.Add(ParseStruct(element, false, structs, aliases, constants));
        foreach (var element in root.GetProperty("messages").EnumerateArray()) structs.Add(ParseStruct(element, true, structs, aliases, constants));
        Unique(structs.Select(item => item.Name), "struct or message");
        Unique(structs.Where(item => item.Opcode is not null).Select(item => item.Opcode!.Value.ToString("X4", CultureInfo.InvariantCulture)), "opcode");

        return new WireProtocol(schemaFormat, generator, Str(root, "name"), Int(root, "protocol"),
            Str(cpp, "namespace"), Str(cpp, "header"), Str(cpp, "dump_header"),
            Str(rust, "file"), Str(rust, "pin_dir"), Str(root, "fixtures"),
            Int(merged, "shift"), merged.GetProperty("sources").EnumerateArray().Select(item => item.GetInt32()).ToArray(),
            constants, structs);
    }

    private static WireConstant ParseConstant(JsonElement element)
    {
        Only(element, "constant", "name", "type", "value", "doc");
        var type = Str(element, "type");
        if (type is not ("u8" or "u16" or "u32" or "u64" or "usize")) throw new InvalidDataException($"Constant type {type} is not known.");
        var value = element.GetProperty("value");
        var hex = value.ValueKind == JsonValueKind.String;
        var number = hex ? ParseNumber(value.GetString()!) : value.GetUInt64();
        return new WireConstant(Str(element, "name"), type, number, hex, Opt(element, "doc") ?? "");
    }

    private static ulong ParseNumber(string text) => text.StartsWith("0x", StringComparison.OrdinalIgnoreCase)
        ? ulong.Parse(text[2..], NumberStyles.HexNumber, CultureInfo.InvariantCulture)
        : ulong.Parse(text, CultureInfo.InvariantCulture);

    private static WireStruct ParseStruct(JsonElement element, bool message, List<WireStruct> known, Dictionary<string, JsonElement> aliases, WireConstant[] constants)
    {
        if (message) Only(element, "message", "name", "opcode", "direction", "validate", "status", "doc", "fields");
        else Only(element, "struct", "name", "rust_tuple", "doc", "fields");

        var name = Str(element, "name");
        var fields = element.GetProperty("fields").EnumerateArray().Select(field => ParseField(field, known, aliases, constants)).ToArray();
        Unique(fields.Select(field => field.Name), $"field of {name}");
        foreach (var field in fields)
            foreach (var check in field.Strict)
                if (check.StartsWith("zero_unless:", StringComparison.Ordinal) && !fields.Any(other => other.Name == check["zero_unless:".Length..] && other.Type is WireOptional))
                    throw new InvalidDataException($"{name}.{field.Name}: {check} names no optional field.");

        ushort? opcode = null;
        var strict = false;
        var direction = "";
        if (message)
        {
            if (Opt(element, "opcode") is { } opcodeText) opcode = (ushort)ParseNumber(opcodeText);
            direction = Str(element, "direction");
            if (direction is not ("c2s" or "s2c")) throw new InvalidDataException($"{name}: direction must be c2s or s2c.");
            var validate = Str(element, "validate");
            if (validate is not ("strict" or "lenient")) throw new InvalidDataException($"{name}: validate must be strict or lenient.");
            strict = validate == "strict";
        }
        var tuple = !message && element.TryGetProperty("rust_tuple", out var tupleElement) && tupleElement.GetBoolean();
        var doc = Opt(element, "doc") ?? "";
        if (message && Opt(element, "status") is { } status)
        {
            if (status != "client_proposal") throw new InvalidDataException($"{name}: status must be client_proposal, or absent.");
            doc = ("Client proposal, not yet on the server. " + doc).TrimEnd();
        }
        return new WireStruct(name, tuple, doc, fields, opcode, message, strict, direction);
    }

    private static WireField ParseField(JsonElement element, List<WireStruct> known, Dictionary<string, JsonElement> aliases, WireConstant[] constants)
    {
        Only(element, "field", "name", "type", "const", "magic", "strict", "item_strict", "count", "max", "of", "flag", "len", "doc");
        var name = Str(element, "name");
        var doc = Opt(element, "doc") ?? "";
        var magic = Opt(element, "magic");
        if (magic is not null)
        {
            if (magic.Length == 0 || magic.Any(character => character is < ' ' or > '~')) throw new InvalidDataException($"{name}: a magic is printable ASCII.");
            return new WireField(name, null, null, magic, [], doc);
        }
        var constant = Opt(element, "const");
        if (constant is not null && !constant.All(char.IsDigit) && constants.All(item => item.Name != constant))
            throw new InvalidDataException($"{name}: constant {constant} is not defined.");
        var type = ParseType(element, known, aliases, constants, name);
        if (constant is not null && type is not WirePrimitive) throw new InvalidDataException($"{name}: a const field is a plain integer.");
        var strict = Checks(element, "strict");
        foreach (var check in strict)
            if (check != "nonzero" && check != "merged_id" && !check.StartsWith("max:", StringComparison.Ordinal) && !check.StartsWith("zero_unless:", StringComparison.Ordinal) && type is not WireList)
                throw new InvalidDataException($"{name}: strict check {check} is not known.");
        return new WireField(name, type, constant, null, type is WireList ? [] : strict, doc);
    }

    private static WireType ParseType(JsonElement element, List<WireStruct> known, Dictionary<string, JsonElement> aliases, WireConstant[] constants, string context)
    {
        var type = Str(element, "type");
        switch (type)
        {
            case "u8" or "u16" or "u32" or "u64": return new WirePrimitive(type);
            case "bool8": return new WireBool();
            case "bytes": return new WireBytes(Int(element, "len"));
            case "list":
            {
                var count = Str(element, "count");
                if (count is not ("u8" or "u16")) throw new InvalidDataException($"{context}: a list count is u8 or u16.");
                var max = Opt(element, "max");
                if (max is not null && constants.All(item => item.Name != max)) throw new InvalidDataException($"{context}: constant {max} is not defined.");
                int? strictMin = null; string? ascending = null; var unique = false;
                foreach (var check in Checks(element, "strict"))
                {
                    if (check.StartsWith("min:", StringComparison.Ordinal)) strictMin = int.Parse(check[4..], CultureInfo.InvariantCulture);
                    else if (check.StartsWith("ascending:", StringComparison.Ordinal)) ascending = check[10..];
                    else if (check == "unique") unique = true;
                    else throw new InvalidDataException($"{context}: list check {check} is not known.");
                }
                var item = ParseOf(element, known, aliases, constants, context);
                if (ascending is not null && (item is not WireStructRef reference || known.First(entry => entry.Name == reference.Name).Values.All(field => field.Name != ascending)))
                    throw new InvalidDataException($"{context}: ascending:{ascending} names no field of the list's items.");
                var itemStrict = Checks(element, "item_strict");
                if (itemStrict.Any(check => check != "nonzero")) throw new InvalidDataException($"{context}: only nonzero applies to list items.");
                return new WireList(new WirePrimitive(count), max, item, strictMin, ascending, unique, itemStrict);
            }
            case "optional": return new WireOptional(Str(element, "flag"), ParseOf(element, known, aliases, constants, context));
            case "tagged":
            {
                var target = Str(element, "of");
                var block = known.FirstOrDefault(item => item.Name == target) ?? throw new InvalidDataException($"{context}: {target} must be defined before it is used.");
                if (block.Fields.Count == 0 || block.Fields[0].Magic is null) throw new InvalidDataException($"{context}: a tagged block starts with a magic.");
                return new WireTagged(target);
            }
        }
        if (aliases.TryGetValue(type, out var alias)) return ParseType(alias, known, aliases, constants, context);
        if (known.Any(item => item.Name == type)) return new WireStructRef(type);
        throw new InvalidDataException($"{context}: type {type} is not defined before its use.");
    }

    private static WireType ParseOf(JsonElement element, List<WireStruct> known, Dictionary<string, JsonElement> aliases, WireConstant[] constants, string context)
    {
        var of = Str(element, "of");
        if (of is "u8" or "u16" or "u32" or "u64") return new WirePrimitive(of);
        if (aliases.TryGetValue(of, out var alias)) return ParseType(alias, known, aliases, constants, context);
        if (known.Any(item => item.Name == of)) return new WireStructRef(of);
        throw new InvalidDataException($"{context}: type {of} is not defined before its use.");
    }

    private static string[] Checks(JsonElement element, string property) =>
        element.TryGetProperty(property, out var checks) ? checks.EnumerateArray().Select(item => item.GetString()!).ToArray() : [];

    private static void Only(JsonElement element, string what, params string[] allowed)
    {
        foreach (var property in element.EnumerateObject())
            if (!allowed.Contains(property.Name, StringComparer.Ordinal))
                throw new InvalidDataException($"Unknown {what} key: {property.Name}.");
    }

    private static void Unique(IEnumerable<string> names, string what)
    {
        var seen = new HashSet<string>(StringComparer.Ordinal);
        foreach (var name in names)
            if (!seen.Add(name)) throw new InvalidDataException($"Duplicate {what}: {name}.");
    }

    private static string Str(JsonElement element, string property) =>
        element.TryGetProperty(property, out var value) && value.ValueKind == JsonValueKind.String
            ? value.GetString()!
            : throw new InvalidDataException($"Missing string {property}.");

    private static string? Opt(JsonElement element, string property) =>
        element.TryGetProperty(property, out var value) ? value.GetString() : null;

    private static int Int(JsonElement element, string property) =>
        element.TryGetProperty(property, out var value) && value.ValueKind == JsonValueKind.Number
            ? value.GetInt32()
            : throw new InvalidDataException($"Missing number {property}.");
}

public static class WireNames
{
    /// <summary>A C++ comment within the server's 120 columns, wrapped on words. Nothing for no text.</summary>
    public static void Comment(StringBuilder o, string text, string indent)
    {
        var line = "";
        foreach (var word in text.Split(' ', StringSplitOptions.RemoveEmptyEntries))
        {
            if (line.Length > 0 && indent.Length + 3 + line.Length + 1 + word.Length > 118)
            {
                o.Append(indent).Append("// ").Append(line).Append('\n');
                line = "";
            }
            line += (line.Length > 0 ? " " : "") + word;
        }
        if (line.Length > 0) o.Append(indent).Append("// ").Append(line).Append('\n');
    }

    public static string Pascal(string snake) => string.Concat(snake.Split('_').Select(word => char.ToUpperInvariant(word[0]) + word[1..]));
    public static string UpperPascal(string upper) => Pascal(upper.ToLowerInvariant());
    public static string Number(WireConstant constant) => constant.Hex
        ? "0x" + constant.Value.ToString("X2", CultureInfo.InvariantCulture)
        : constant.Value.ToString(CultureInfo.InvariantCulture);
}

internal static class WireCppEmitter
{
    private static string Guard(WireProtocol protocol, string file) =>
        string.Concat(file.Select(character => char.IsLetterOrDigit(character) ? char.ToUpperInvariant(character) : '_')) + "_INCLUDED";

    private static string Prim(string name) => name switch { "u8" => "std::uint8_t", "u16" => "std::uint16_t", "u32" => "std::uint32_t", "u64" => "std::uint64_t", "usize" => "std::size_t", _ => throw new InvalidOperationException(name) };

    private static string TypeOf(WireType type) => type switch
    {
        WirePrimitive primitive => Prim(primitive.Name),
        WireBool => "bool",
        WireBytes bytes => $"std::array<std::uint8_t, {bytes.Length}>",
        WireList list => $"std::vector<{TypeOf(list.Item)}>",
        WireStructRef reference => WireNames.Pascal(reference.Name),
        WireOptional optional => $"std::optional<{TypeOf(optional.Inner)}>",
        WireTagged tagged => $"std::optional<{WireNames.Pascal(tagged.Name)}>",
        _ => throw new InvalidOperationException()
    };

    private static string Const(WireProtocol protocol, string name) => name.All(char.IsDigit) ? name : WireNames.UpperPascal(name);

    public static string Codec(WireProtocol protocol)
    {
        var o = new StringBuilder();
        var guard = Guard(protocol, protocol.CppHeader);
        o.Append($"#ifndef {guard}\n#define {guard}\n\n");
        o.Append("#include <algorithm>\n#include <array>\n#include <cstddef>\n#include <cstdint>\n#include <optional>\n#include <span>\n#include <utility>\n#include <vector>\n\n");
        o.Append("// Wire shape only. Decoders of messages marked strict in the definition also apply its checks;\n");
        o.Append("// permissions, catalog membership, saving and cost stay ordinary code.\n");
        o.Append($"namespace {protocol.CppNamespace}\n{{\n");
        foreach (var constant in protocol.Constants)
        {
            WireNames.Comment(o, constant.Doc, "");
            o.Append($"inline constexpr {Prim(constant.Type)} {WireNames.UpperPascal(constant.Name)} = {WireNames.Number(constant)};\n");
        }
        o.Append('\n');
        foreach (var message in protocol.Messages)
        {
            var pascal = WireNames.Pascal(message.Name);
            if (message.Opcode is { } opcode) o.Append($"inline constexpr std::uint16_t Op{pascal} = 0x{opcode:X4};\n");
            o.Append(CultureInfo.InvariantCulture, $"inline constexpr std::size_t {pascal}MaxBody = {protocol.MaxSize(message)};\n");
        }
        o.Append('\n');
        foreach (var item in protocol.Structs)
        {
            WireNames.Comment(o, item.Doc, "");
            o.Append($"struct {WireNames.Pascal(item.Name)}\n{{\n");
            foreach (var field in item.Values)
            {
                WireNames.Comment(o, field.Doc, "    ");
                var init = field.Type is WirePrimitive ? " = 0" : field.Type is WireBool ? " = false" : field.Type is WireBytes ? "{}" : "";
                o.Append($"    {TypeOf(field.Type!)} {WireNames.Pascal(field.Name)}{init};\n");
            }
            o.Append($"    bool operator==({WireNames.Pascal(item.Name)} const&) const = default;\n}};\n\n");
        }
        Helpers(protocol, o);
        foreach (var item in protocol.Structs)
        {
            ReadFunction(protocol, item, o);
            WriteFunction(protocol, item, o);
        }
        o.Append("} // namespace Detail\n\n");
        foreach (var message in protocol.Messages)
        {
            var pascal = WireNames.Pascal(message.Name);
            WireNames.Comment(o, message.Doc, "");
            var strict = message.Strict ? "true" : "false";
            o.Append($"inline std::optional<{pascal}> Decode{pascal}(std::span<std::uint8_t const> bytes)\n{{\n");
            o.Append($"    Detail::Cursor cursor{{bytes}};\n    {pascal} value;\n");
            o.Append($"    if (!Detail::Read{pascal}(cursor, value, {strict}) || !cursor.Rest.empty())\n        return std::nullopt;\n    return value;\n}}\n\n");
            o.Append($"inline std::optional<std::vector<std::uint8_t>> Encode{pascal}({pascal} const& value)\n{{\n");
            o.Append($"    std::vector<std::uint8_t> out;\n    if (!Detail::Write{pascal}(out, value))\n        return std::nullopt;\n    return out;\n}}\n\n");
        }
        o.Append($"}} // namespace {protocol.CppNamespace}\n\n#endif\n");
        return o.ToString();
    }

    private static void Helpers(WireProtocol protocol, StringBuilder o)
    {
        o.Append("namespace Detail\n{\n");
        o.Append("struct Cursor\n{\n    std::span<std::uint8_t const> Rest;\n\n");
        o.Append("    template<typename T>\n    bool Read(T& value)\n    {\n        if (Rest.size() < sizeof(T))\n            return false;\n        value = 0;\n");
        o.Append("        for (std::size_t i = 0; i < sizeof(T); ++i)\n            value |= static_cast<T>(static_cast<T>(Rest[i]) << (8 * i));\n");
        o.Append("        Rest = Rest.subspan(sizeof(T));\n        return true;\n    }\n\n");
        o.Append("    bool ReadFlag(bool& value, bool strict)\n    {\n        std::uint8_t raw = 0;\n        if (!Read(raw) || (strict && raw > 1))\n            return false;\n        value = raw != 0;\n        return true;\n    }\n\n");
        o.Append("    bool StartsWith(char const* magic, std::size_t size) const\n    {\n        return Rest.size() >= size && std::equal(magic, magic + size, Rest.begin(),\n            [](char a, std::uint8_t b) { return static_cast<std::uint8_t>(a) == b; });\n    }\n\n");
        o.Append("    bool Eat(char const* magic, std::size_t size)\n    {\n        if (!StartsWith(magic, size))\n            return false;\n        Rest = Rest.subspan(size);\n        return true;\n    }\n};\n\n");
        o.Append("template<typename T>\ninline void Put(std::vector<std::uint8_t>& out, T value)\n{\n    for (std::size_t i = 0; i < sizeof(T); ++i)\n        out.push_back(static_cast<std::uint8_t>(value >> (8 * i)));\n}\n\n");
        var sources = string.Join(" || ", protocol.MergedSources.Select(source => $"source == {source}"));
        var mask = (1UL << protocol.MergedShift) - 1;
        o.Append($"constexpr bool IsMergedId(std::uint32_t id)\n{{\n    auto const source = id >> {protocol.MergedShift};\n    return ({sources}) && (id & 0x{mask:X8}) != 0;\n}}\n\n");
    }

    private static string ScalarCheck(string check, string place) => check switch
    {
        "nonzero" => $"{place} != 0",
        "merged_id" => $"IsMergedId({place})",
        _ when check.StartsWith("max:", StringComparison.Ordinal) => $"{place} <= {check[4..]}",
        _ => throw new InvalidOperationException(check)
    };

    private static void ReadValue(WireProtocol protocol, WireType type, string place, string indent, int depth, StringBuilder o)
    {
        switch (type)
        {
            case WirePrimitive:
                o.Append($"{indent}if (!c.Read({place}))\n{indent}    return false;\n");
                break;
            case WireBool:
                o.Append($"{indent}if (!c.ReadFlag({place}, strict))\n{indent}    return false;\n");
                break;
            case WireBytes:
                o.Append($"{indent}for (auto& byte : {place})\n{indent}    if (!c.Read(byte))\n{indent}        return false;\n");
                break;
            case WireStructRef reference:
                o.Append($"{indent}if (!Read{WireNames.Pascal(reference.Name)}(c, {place}, strict))\n{indent}    return false;\n");
                break;
            case WireList list:
            {
                var count = $"count{depth}";
                var limit = list.MaxConstant is { } max ? $" || {count} > {WireNames.UpperPascal(max)}" : "";
                o.Append($"{indent}{{\n{indent}    {Prim(list.Count.Name)} {count} = 0;\n{indent}    if (!c.Read({count}){limit})\n{indent}        return false;\n");
                o.Append($"{indent}    {place}.clear();\n{indent}    {place}.reserve(std::min<std::size_t>({count}, c.Rest.size()));\n");
                o.Append($"{indent}    for (std::size_t i{depth} = 0; i{depth} < {count}; ++i{depth})\n{indent}    {{\n");
                o.Append($"{indent}        {TypeOf(list.Item)} item{depth}{{}};\n");
                ReadValue(protocol, list.Item, $"item{depth}", indent + "        ", depth + 1, o);
                o.Append($"{indent}        {place}.push_back(std::move(item{depth}));\n{indent}    }}\n{indent}}}\n");
                break;
            }
            case WireOptional optional:
            {
                var flag = $"{optional.Flag}{depth}";
                o.Append($"{indent}bool {flag} = false;\n{indent}if (!c.ReadFlag({flag}, strict))\n{indent}    return false;\n");
                o.Append($"{indent}if ({flag})\n{indent}{{\n{indent}    {place}.emplace();\n");
                ReadValue(protocol, optional.Inner, $"(*{place})", indent + "    ", depth + 1, o);
                o.Append($"{indent}}}\n");
                break;
            }
            case WireTagged tagged:
            {
                var magic = protocol.Find(tagged.Name).Fields[0].Magic!;
                o.Append($"{indent}if (c.StartsWith(\"{magic}\", {magic.Length}))\n{indent}{{\n{indent}    {place}.emplace();\n");
                o.Append($"{indent}    if (!Read{WireNames.Pascal(tagged.Name)}(c, *{place}, strict))\n{indent}        return false;\n{indent}}}\n");
                break;
            }
        }
    }

    private static void ListChecks(WireList list, string place, StringBuilder o)
    {
        if (list.StrictMin is { } min) o.Append($"    if (strict && {place}.size() < {min})\n        return false;\n");
        if (list.StrictAscending is { } key)
        {
            var name = WireNames.Pascal(key);
            o.Append($"    if (strict)\n        for (std::size_t i = 1; i < {place}.size(); ++i)\n            if ({place}[i].{name} <= {place}[i - 1].{name})\n                return false;\n");
        }
        if (list.StrictUnique)
            o.Append($"    if (strict)\n        for (std::size_t i = 1; i < {place}.size(); ++i)\n            if (std::find({place}.begin(), {place}.begin() + i, {place}[i]) != {place}.begin() + i)\n                return false;\n");
        if (list.ItemStrict.Contains("nonzero"))
            o.Append($"    if (strict)\n        for (auto const& item : {place})\n            if (item == 0)\n                return false;\n");
    }

    private static void ReadFunction(WireProtocol protocol, WireStruct item, StringBuilder o)
    {
        var pascal = WireNames.Pascal(item.Name);
        o.Append($"inline bool Read{pascal}(Cursor& c, {pascal}& v, bool strict)\n{{\n");
        o.Append("    (void)c;\n    (void)v;\n    (void)strict;\n");
        foreach (var field in item.Fields)
        {
            if (field.Magic is { } magic)
            {
                o.Append($"    if (!c.Eat(\"{magic}\", {magic.Length}))\n        return false;\n");
            }
            else if (field.Const is { } constant)
            {
                var name = WireNames.Pascal(field.Name);
                o.Append($"    {TypeOf(field.Type!)} {name.ToLowerInvariant()} = 0;\n    if (!c.Read({name.ToLowerInvariant()}) || {name.ToLowerInvariant()} != {Const(protocol, constant)})\n        return false;\n");
            }
            else
            {
                ReadValue(protocol, field.Type!, $"v.{WireNames.Pascal(field.Name)}", "    ", 0, o);
            }
        }
        // Checks follow every read: which one fails does not matter, a decode is all or nothing.
        foreach (var field in item.Values)
        {
            var place = $"v.{WireNames.Pascal(field.Name)}";
            foreach (var check in field.Strict)
            {
                if (check.StartsWith("zero_unless:", StringComparison.Ordinal))
                    o.Append($"    if (strict && {place} != 0 && !v.{WireNames.Pascal(check["zero_unless:".Length..])})\n        return false;\n");
                else
                    o.Append($"    if (strict && !({ScalarCheck(check, place)}))\n        return false;\n");
            }
            var list = field.Type switch { WireList direct => direct, WireOptional { Inner: WireList inner } => inner, _ => null };
            if (list is null) continue;
            if (field.Type is WireOptional)
            {
                var body = new StringBuilder();
                ListChecks(list, "inner", body);
                if (body.Length == 0) continue;
                o.Append($"    if ({place})\n    {{\n        auto const& inner = *{place};\n");
                o.Append(string.Concat(body.ToString().Split('\n', StringSplitOptions.RemoveEmptyEntries).Select(line => "    " + line + "\n")));
                o.Append("    }\n");
            }
            else ListChecks(list, place, o);
        }
        o.Append("    return true;\n}\n\n");
    }

    private static void WriteValue(WireProtocol protocol, WireType type, string place, string indent, int depth, StringBuilder o)
    {
        switch (type)
        {
            case WirePrimitive:
                o.Append($"{indent}Put(out, {place});\n");
                break;
            case WireBool:
                o.Append($"{indent}Put(out, static_cast<std::uint8_t>({place} ? 1 : 0));\n");
                break;
            case WireBytes:
                o.Append($"{indent}out.insert(out.end(), {place}.begin(), {place}.end());\n");
                break;
            case WireStructRef reference:
                o.Append($"{indent}if (!Write{WireNames.Pascal(reference.Name)}(out, {place}))\n{indent}    return false;\n");
                break;
            case WireList list:
            {
                var limit = list.MaxConstant is { } max ? WireNames.UpperPascal(max) : protocol.ListLimit(list).ToString(CultureInfo.InvariantCulture);
                o.Append($"{indent}if ({place}.size() > {limit})\n{indent}    return false;\n");
                o.Append($"{indent}Put(out, static_cast<{Prim(list.Count.Name)}>({place}.size()));\n");
                o.Append($"{indent}for (auto const& item{depth} : {place})\n{indent}{{\n");
                WriteValue(protocol, list.Item, $"item{depth}", indent + "    ", depth + 1, o);
                o.Append($"{indent}}}\n");
                break;
            }
            case WireOptional optional:
                o.Append($"{indent}Put(out, static_cast<std::uint8_t>({place} ? 1 : 0));\n{indent}if ({place})\n{indent}{{\n");
                WriteValue(protocol, optional.Inner, $"(*{place})", indent + "    ", depth + 1, o);
                o.Append($"{indent}}}\n");
                break;
            case WireTagged tagged:
                o.Append($"{indent}if ({place} && !Write{WireNames.Pascal(tagged.Name)}(out, *{place}))\n{indent}    return false;\n");
                break;
        }
    }

    private static void WriteFunction(WireProtocol protocol, WireStruct item, StringBuilder o)
    {
        var pascal = WireNames.Pascal(item.Name);
        o.Append($"inline bool Write{pascal}(std::vector<std::uint8_t>& out, {pascal} const& v)\n{{\n    (void)out;\n    (void)v;\n");
        foreach (var field in item.Fields)
        {
            if (field.Magic is { } magic)
                o.Append($"    out.insert(out.end(), {{{string.Join(", ", magic.Select(character => $"'{character}'"))}}});\n");
            else if (field.Const is { } constant)
                o.Append($"    Put(out, static_cast<{TypeOf(field.Type!)}>({Const(protocol, constant)}));\n");
            else
                WriteValue(protocol, field.Type!, $"v.{WireNames.Pascal(field.Name)}", "    ", 0, o);
        }
        o.Append("    return true;\n}\n\n");
    }

    public static string Dump(WireProtocol protocol)
    {
        var o = new StringBuilder();
        var guard = Guard(protocol, protocol.CppDumpHeader);
        o.Append($"#ifndef {guard}\n#define {guard}\n\n#include \"{protocol.CppHeader}\"\n\n#include <string>\n#include <string_view>\n\n");
        o.Append("// Test support: canonical text of decoded values, compared with the fixtures and across languages.\n");
        o.Append($"namespace {protocol.CppNamespace}\n{{\n");
        foreach (var item in protocol.Structs)
        {
            var pascal = WireNames.Pascal(item.Name);
            o.Append($"inline std::string Dump({pascal} const& v)\n{{\n    (void)v;\n    std::string s = \"{{\";\n");
            var first = true;
            foreach (var field in item.Values)
            {
                o.Append($"    s += \"{(first ? "" : ",")}{field.Name}=\";\n");
                DumpValue(field.Type!, $"v.{WireNames.Pascal(field.Name)}", "    ", 0, o);
                first = false;
            }
            o.Append("    s += \"}\";\n    return s;\n}\n\n");
        }
        o.Append("struct RoundTrip\n{\n    std::string Text;\n    std::optional<std::vector<std::uint8_t>> Encoded;\n};\n\n");
        o.Append("// Decodes a body by message name, for the fixture runner. No value: it did not decode, or no such message.\n");
        o.Append("inline std::optional<RoundTrip> DecodeByName(std::string_view message, std::span<std::uint8_t const> bytes)\n{\n");
        foreach (var message in protocol.Messages)
        {
            var pascal = WireNames.Pascal(message.Name);
            o.Append($"    if (message == \"{message.Name}\")\n    {{\n        auto value = Decode{pascal}(bytes);\n        if (!value)\n            return std::nullopt;\n");
            o.Append($"        return RoundTrip{{Dump(*value), Encode{pascal}(*value)}};\n    }}\n");
        }
        o.Append("    return std::nullopt;\n}\n\n");
        o.Append($"}} // namespace {protocol.CppNamespace}\n\n#endif\n");
        return o.ToString();
    }

    private static void DumpValue(WireType type, string place, string indent, int depth, StringBuilder o)
    {
        switch (type)
        {
            case WirePrimitive primitive:
                var widen = primitive.Name == "u8" ? $"unsigned({place})" : place;
                o.Append($"{indent}s += std::to_string({widen});\n");
                break;
            case WireBool:
                o.Append($"{indent}s += {place} ? \"1\" : \"0\";\n");
                break;
            case WireBytes:
                o.Append($"{indent}s += \"[\";\n{indent}for (std::size_t i = 0; i < {place}.size(); ++i)\n{indent}    s += (i ? \",\" : \"\") + std::to_string(unsigned({place}[i]));\n{indent}s += \"]\";\n");
                break;
            case WireStructRef:
                o.Append($"{indent}s += Dump({place});\n");
                break;
            case WireList list:
                o.Append($"{indent}s += \"[\";\n{indent}for (std::size_t i{depth} = 0; i{depth} < {place}.size(); ++i{depth})\n{indent}{{\n{indent}    if (i{depth})\n{indent}        s += \",\";\n");
                DumpValue(list.Item, $"{place}[i{depth}]", indent + "    ", depth + 1, o);
                o.Append($"{indent}}}\n{indent}s += \"]\";\n");
                break;
            case WireOptional optional:
                o.Append($"{indent}if (!{place})\n{indent}    s += \"none\";\n{indent}else\n{indent}{{\n");
                DumpValue(optional.Inner, $"(*{place})", indent + "    ", depth + 1, o);
                o.Append($"{indent}}}\n");
                break;
            case WireTagged:
                o.Append($"{indent}s += {place} ? Dump(*{place}) : std::string(\"none\");\n");
                break;
        }
    }
}

internal static class WireRustEmitter
{
    private static string TypeOf(WireType type) => type switch
    {
        WirePrimitive primitive => primitive.Name,
        WireBool => "bool",
        WireBytes bytes => $"[u8; {bytes.Length}]",
        WireList list => $"Vec<{TypeOf(list.Item)}>",
        WireStructRef reference => WireNames.Pascal(reference.Name),
        WireOptional optional => $"Option<{TypeOf(optional.Inner)}>",
        WireTagged tagged => $"Option<{WireNames.Pascal(tagged.Name)}>",
        _ => throw new InvalidOperationException()
    };

    private static bool IsCopy(WireStruct item) =>
        item.Values.All(field => field.Type is WirePrimitive or WireBool or WireBytes);

    public static string Emit(WireProtocol protocol)
    {
        var o = new StringBuilder();
        o.Append("//! The wire shape of this protocol, generated from its definition. Decoders of messages marked\n//! strict there also apply its checks; everything a value means stays ordinary code.\n\n");
        o.Append("#![allow(unused_variables, unused_mut, clippy::all)]\n\n");
        o.Append("/// SHA-256 of the definition this was generated from, with its line endings as LF.\n");
        o.Append($"pub const SCHEMA_VERSION: u32 = {protocol.SchemaFormat};\npub const GENERATOR_VERSION: u32 = {WireProtocolGenerator.GeneratorVersion};\npub const PROTOCOL_VERSION: u32 = {protocol.Version};\n\n");
        foreach (var constant in protocol.Constants)
        {
            if (constant.Doc.Length > 0) o.Append($"/// {constant.Doc}\n");
            o.Append($"pub const {constant.Name}: {constant.Type} = {WireNames.Number(constant)};\n");
        }
        o.Append('\n');
        foreach (var message in protocol.Messages)
        {
            var upper = message.Name.ToUpperInvariant();
            if (message.Opcode is { } opcode) o.Append($"pub const OP_{upper}: u16 = 0x{opcode:X4};\n");
            o.Append(CultureInfo.InvariantCulture, $"pub const {upper}_MAX_BODY: usize = {protocol.MaxSize(message)};\n");
        }
        o.Append('\n');
        foreach (var item in protocol.Structs)
        {
            var pascal = WireNames.Pascal(item.Name);
            if (item.Doc.Length > 0) o.Append($"/// {item.Doc}\n");
            if (item.RustTuple)
            {
                o.Append($"pub type {pascal} = ({string.Join(", ", item.Values.Select(field => TypeOf(field.Type!)))});\n\n");
                continue;
            }
            o.Append(IsCopy(item)
                ? "#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]\n"
                : "#[derive(Debug, Clone, PartialEq, Eq, Default)]\n");
            o.Append($"pub struct {pascal} {{\n");
            foreach (var field in item.Values)
            {
                if (field.Doc.Length > 0) o.Append($"    /// {field.Doc}\n");
                o.Append($"    pub {field.Name}: {TypeOf(field.Type!)},\n");
            }
            o.Append("}\n\n");
        }
        Helpers(protocol, o);
        foreach (var item in protocol.Structs)
        {
            ReadFunction(protocol, item, o);
            WriteFunction(protocol, item, o);
        }
        foreach (var message in protocol.Messages)
        {
            var pascal = WireNames.Pascal(message.Name);
            if (message.Doc.Length > 0) o.Append($"/// {message.Doc}\n");
            o.Append($"pub fn decode_{message.Name}(bytes: &[u8]) -> Option<{pascal}> {{\n    let mut c = Cursor(bytes);\n    let value = read_{message.Name}(&mut c, {(message.Strict ? "true" : "false")})?;\n    c.0.is_empty().then_some(value)\n}}\n\n");
            o.Append($"/// `None` when a list is past its limit.\npub fn encode_{message.Name}(value: &{pascal}) -> Option<Vec<u8>> {{\n    let mut out = Vec::new();\n    write_{message.Name}(&mut out, value)?;\n    Some(out)\n}}\n\n");
        }
        Dump(protocol, o);
        return o.ToString();
    }

    private static void Helpers(WireProtocol protocol, StringBuilder o)
    {
        o.Append("struct Cursor<'a>(&'a [u8]);\n\nimpl Cursor<'_> {\n");
        o.Append("    fn take<const N: usize>(&mut self) -> Option<[u8; N]> {\n        let (head, rest) = self.0.split_first_chunk::<N>()?;\n        self.0 = rest;\n        Some(*head)\n    }\n");
        o.Append("    fn u8(&mut self) -> Option<u8> {\n        self.take::<1>().map(|b| b[0])\n    }\n");
        o.Append("    fn u16(&mut self) -> Option<u16> {\n        self.take().map(u16::from_le_bytes)\n    }\n");
        o.Append("    fn u32(&mut self) -> Option<u32> {\n        self.take().map(u32::from_le_bytes)\n    }\n");
        o.Append("    fn u64(&mut self) -> Option<u64> {\n        self.take().map(u64::from_le_bytes)\n    }\n");
        o.Append("    fn flag(&mut self, strict: bool) -> Option<bool> {\n        let raw = self.u8()?;\n        (!strict || raw <= 1).then_some(raw != 0)\n    }\n");
        o.Append("    fn eat(&mut self, magic: &[u8]) -> Option<()> {\n        self.0 = self.0.strip_prefix(magic)?;\n        Some(())\n    }\n}\n\n");
        var sources = string.Join(" | ", protocol.MergedSources);
        var mask = (1UL << protocol.MergedShift) - 1;
        o.Append($"/// A source-qualified catalog id: a known source in the high bits, a native id under them.\npub const fn is_merged_id(id: u32) -> bool {{\n    matches!(id >> {protocol.MergedShift}, {sources}) && id & 0x{mask:X8} != 0\n}}\n\n");
    }

    private static string ReadValue(WireProtocol protocol, WireType type, string indent, int depth)
    {
        switch (type)
        {
            case WirePrimitive primitive: return $"c.{primitive.Name}()?";
            case WireBool: return "c.flag(strict)?";
            case WireBytes bytes: return $"c.take::<{bytes.Length}>()?";
            case WireStructRef reference: return $"read_{reference.Name}(c, strict)?";
            case WireTagged tagged:
            {
                var magic = protocol.Find(tagged.Name).Fields[0].Magic!;
                return $"if c.0.starts_with(b\"{magic}\") {{\n{indent}    Some(read_{tagged.Name}(c, strict)?)\n{indent}}} else {{\n{indent}    None\n{indent}}}";
            }
            case WireOptional optional:
                return $"if c.flag(strict)? {{\n{indent}    Some({ReadValue(protocol, optional.Inner, indent + "    ", depth + 1)})\n{indent}}} else {{\n{indent}    None\n{indent}}}";
            case WireList list:
            {
                var read = $"usize::from(c.{list.Count.Name}()?)";
                var limit = list.MaxConstant is { } max ? $"\n{indent}    if n{depth} > {max} {{\n{indent}        return None;\n{indent}    }}" : "";
                return $"{{\n{indent}    let n{depth} = {read};{limit}\n{indent}    let mut v{depth} = Vec::with_capacity(n{depth}.min(c.0.len()));\n{indent}    for _ in 0..n{depth} {{\n{indent}        v{depth}.push({ReadValue(protocol, list.Item, indent + "        ", depth + 1)});\n{indent}    }}\n{indent}    v{depth}\n{indent}}}";
            }
            default: throw new InvalidOperationException();
        }
    }

    private static string Member(WireProtocol protocol, WireType item, string key, string element)
    {
        var target = protocol.Find(((WireStructRef)item).Name);
        if (!target.RustTuple) return $"{element}.{key}";
        return $"{element}.{target.Values.Select(field => field.Name).ToList().IndexOf(key)}";
    }

    private static void ListChecks(WireProtocol protocol, WireList list, string place, string indent, StringBuilder o)
    {
        if (list.StrictMin is { } min) o.Append($"{indent}if strict && {place}.len() < {min} {{\n{indent}    return None;\n{indent}}}\n");
        if (list.StrictAscending is { } key)
            o.Append($"{indent}if strict && !{place}.windows(2).all(|w| {Member(protocol, list.Item, key, "w[0]")} < {Member(protocol, list.Item, key, "w[1]")}) {{\n{indent}    return None;\n{indent}}}\n");
        if (list.StrictUnique)
            o.Append($"{indent}if strict && (1..{place}.len()).any(|i| {place}[..i].contains(&{place}[i])) {{\n{indent}    return None;\n{indent}}}\n");
        if (list.ItemStrict.Contains("nonzero"))
            o.Append($"{indent}if strict && {place}.iter().any(|&item| item == 0) {{\n{indent}    return None;\n{indent}}}\n");
    }

    private static void ReadFunction(WireProtocol protocol, WireStruct item, StringBuilder o)
    {
        var pascal = WireNames.Pascal(item.Name);
        o.Append($"fn read_{item.Name}(c: &mut Cursor<'_>, strict: bool) -> Option<{pascal}> {{\n");
        foreach (var field in item.Fields)
        {
            if (field.Magic is { } magic) o.Append($"    c.eat(b\"{magic}\")?;\n");
            else if (field.Const is { } constant)
                o.Append($"    if c.{((WirePrimitive)field.Type!).Name}()? != {constant} {{\n        return None;\n    }}\n");
            else
                o.Append($"    let {field.Name} = {ReadValue(protocol, field.Type!, "    ", 0)};\n");
        }
        foreach (var field in item.Values)
        {
            foreach (var check in field.Strict)
            {
                var condition = check switch
                {
                    "nonzero" => $"{field.Name} == 0",
                    "merged_id" => $"!is_merged_id({field.Name})",
                    _ when check.StartsWith("max:", StringComparison.Ordinal) => $"{field.Name} > {check[4..]}",
                    _ when check.StartsWith("zero_unless:", StringComparison.Ordinal) => $"{field.Name} != 0 && {check["zero_unless:".Length..]}.is_none()",
                    _ => throw new InvalidOperationException(check)
                };
                o.Append($"    if strict && {condition} {{\n        return None;\n    }}\n");
            }
            if (field.Type is WireList list) ListChecks(protocol, list, field.Name, "    ", o);
            if (field.Type is WireOptional { Inner: WireList inner })
            {
                var body = new StringBuilder();
                ListChecks(protocol, inner, "inner", "        ", body);
                if (body.Length == 0) continue;
                o.Append($"    if let Some(inner) = &{field.Name} {{\n").Append(body).Append("    }\n");
            }
        }
        var values = item.Values.Select(field => field.Name).ToArray();
        o.Append(item.RustTuple
            ? $"    Some(({string.Join(", ", values)}))\n}}\n\n"
            : values.Length == 0 ? $"    Some({pascal} {{}})\n}}\n\n" : $"    Some({pascal} {{ {string.Join(", ", values)} }})\n}}\n\n");
    }

    private static void WriteValue(WireProtocol protocol, WireType type, string place, string indent, int depth, StringBuilder o)
    {
        switch (type)
        {
            case WirePrimitive primitive when primitive.Name == "u8": o.Append($"{indent}out.push({place});\n"); break;
            case WirePrimitive: o.Append($"{indent}out.extend_from_slice(&{place}.to_le_bytes());\n"); break;
            case WireBool: o.Append($"{indent}out.push(u8::from({place}));\n"); break;
            case WireBytes: o.Append($"{indent}out.extend_from_slice(&{place});\n"); break;
            case WireStructRef reference: o.Append($"{indent}write_{reference.Name}(out, &{place})?;\n"); break;
            case WireTagged tagged:
                o.Append($"{indent}if let Some(block) = &{place} {{\n{indent}    write_{tagged.Name}(out, block)?;\n{indent}}}\n");
                break;
            case WireOptional optional:
                o.Append($"{indent}out.push(u8::from({place}.is_some()));\n{indent}if let Some(inner{depth}) = &{place} {{\n");
                WriteValue(protocol, optional.Inner, $"(*inner{depth})", indent + "    ", depth + 1, o);
                o.Append($"{indent}}}\n");
                break;
            case WireList list:
            {
                var limit = list.MaxConstant ?? protocol.ListLimit(list).ToString(CultureInfo.InvariantCulture);
                o.Append($"{indent}if {place}.len() > {limit} {{\n{indent}    return None;\n{indent}}}\n");
                o.Append(list.Count.Name == "u8"
                    ? $"{indent}out.push({place}.len() as u8);\n"
                    : $"{indent}out.extend_from_slice(&({place}.len() as {list.Count.Name}).to_le_bytes());\n");
                o.Append($"{indent}for item{depth} in {place}.iter() {{\n");
                WriteValue(protocol, list.Item, $"(*item{depth})", indent + "    ", depth + 1, o);
                o.Append($"{indent}}}\n");
                break;
            }
        }
    }

    private static void WriteFunction(WireProtocol protocol, WireStruct item, StringBuilder o)
    {
        var pascal = WireNames.Pascal(item.Name);
        o.Append($"fn write_{item.Name}(out: &mut Vec<u8>, v: &{pascal}) -> Option<()> {{\n");
        var values = item.Values.Select(field => field.Name).ToList();
        foreach (var field in item.Fields)
        {
            if (field.Magic is { } magic) o.Append($"    out.extend_from_slice(b\"{magic}\");\n");
            else if (field.Const is { } constant)
            {
                var primitive = ((WirePrimitive)field.Type!).Name;
                o.Append(primitive == "u8" ? $"    out.push({constant});\n" : $"    out.extend_from_slice(&({constant} as {primitive}).to_le_bytes());\n");
            }
            else
            {
                var place = item.RustTuple ? $"v.{values.IndexOf(field.Name)}" : $"v.{field.Name}";
                WriteValue(protocol, field.Type!, place, "    ", 0, o);
            }
        }
        o.Append("    Some(())\n}\n\n");
    }

    private static void Dump(WireProtocol protocol, StringBuilder o)
    {
        o.Append("/// Test support: canonical text of decoded values, compared with the fixtures and across languages.\n#[doc(hidden)]\npub mod dump {\n    use super::*;\n\n");
        foreach (var item in protocol.Structs)
        {
            var pascal = WireNames.Pascal(item.Name);
            var values = item.Values.ToList();
            o.Append($"    pub fn {item.Name}(v: &{pascal}) -> String {{\n        let mut s = String::from(\"{{\");\n");
            for (var index = 0; index < values.Count; index++)
            {
                var field = values[index];
                var place = item.RustTuple ? $"v.{index}" : $"v.{field.Name}";
                o.Append($"        s.push_str(\"{(index == 0 ? "" : ",")}{field.Name}=\");\n");
                DumpValue(field.Type!, place, "        ", 0, o);
            }
            o.Append("        s.push('}');\n        s\n    }\n\n");
        }
        o.Append("    /// Decodes a body by message name: its text and re-encoding. `None`: it did not decode.\n");
        o.Append("    pub fn decode_by_name(message: &str, bytes: &[u8]) -> Option<(String, Option<Vec<u8>>)> {\n        match message {\n");
        foreach (var message in protocol.Messages)
            o.Append($"            \"{message.Name}\" => decode_{message.Name}(bytes).map(|v| ({message.Name}(&v), encode_{message.Name}(&v))),\n");
        o.Append("            _ => None,\n        }\n    }\n}\n");
    }

    private static void DumpValue(WireType type, string place, string indent, int depth, StringBuilder o)
    {
        switch (type)
        {
            case WirePrimitive: o.Append($"{indent}s.push_str(&{place}.to_string());\n"); break;
            case WireBool: o.Append($"{indent}s.push_str(if {place} {{ \"1\" }} else {{ \"0\" }});\n"); break;
            case WireBytes:
                o.Append($"{indent}s.push('[');\n{indent}s.push_str(&{place}.iter().map(u8::to_string).collect::<Vec<_>>().join(\",\"));\n{indent}s.push(']');\n");
                break;
            case WireStructRef reference: o.Append($"{indent}s.push_str(&{reference.Name}(&{place}));\n"); break;
            case WireTagged tagged:
                o.Append($"{indent}match &{place} {{\n{indent}    Some(block) => s.push_str(&{tagged.Name}(block)),\n{indent}    None => s.push_str(\"none\"),\n{indent}}}\n");
                break;
            case WireOptional optional:
                o.Append($"{indent}match &{place} {{\n{indent}    Some(inner{depth}) => {{\n");
                DumpValue(optional.Inner, $"(*inner{depth})", indent + "        ", depth + 1, o);
                o.Append($"{indent}    }}\n{indent}    None => s.push_str(\"none\"),\n{indent}}}\n");
                break;
            case WireList list:
                o.Append($"{indent}s.push('[');\n{indent}for (i{depth}, item{depth}) in {place}.iter().enumerate() {{\n{indent}    if i{depth} != 0 {{\n{indent}        s.push(',');\n{indent}    }}\n");
                DumpValue(list.Item, $"(*item{depth})", indent + "    ", depth + 1, o);
                o.Append($"{indent}}}\n{indent}s.push(']');\n");
                break;
        }
    }
}

/// <summary>Writes generated files and their client pin, and reports what differs from a definition.</summary>
public sealed record WireProtocolPaths(string Definition, string? CppOut, string? ClientRoot);

public sealed record WireFileState(string Path, string State);

public static class WireProtocolOutputs
{
    /// <summary>Every file the definition should produce, and its exact text.</summary>
    public static IReadOnlyList<(string Path, string Text)> Expected(WireProtocolPaths paths)
    {
        var definitionText = File.ReadAllText(paths.Definition);
        var definitionName = Path.GetFileName(paths.Definition);
        string cppHeader, cppDumpHeader, rustFile, pinDir, fixtureFile;
        WireGeneratedSet generated;
        if (WireTableGenerator.IsTableDefinition(definitionText))
        {
            var tables = WireTableGenerator.Parse(definitionText);
            generated = WireTableGenerator.Generate(tables, definitionText, definitionName);
            (cppHeader, cppDumpHeader, rustFile, pinDir, fixtureFile) = (tables.CppHeader, tables.CppDumpHeader, tables.RustFile, tables.RustPinDir, tables.Fixtures);
        }
        else
        {
            var protocol = WireProtocolGenerator.Parse(definitionText);
            generated = WireProtocolGenerator.Generate(protocol, definitionText, definitionName);
            (cppHeader, cppDumpHeader, rustFile, pinDir, fixtureFile) = (protocol.CppHeader, protocol.CppDumpHeader, protocol.RustFile, protocol.RustPinDir, protocol.Fixtures);
        }
        var files = new List<(string, string)>();
        if (paths.CppOut is { } cpp)
        {
            files.Add((Path.Combine(cpp, cppHeader), generated.CppCodec));
            files.Add((Path.Combine(cpp, cppDumpHeader), generated.CppDump));
        }
        if (paths.ClientRoot is { } client)
        {
            files.Add((Path.Combine(client, rustFile), generated.Rust));
            var pin = Path.Combine(client, pinDir);
            files.Add((Path.Combine(pin, definitionName), definitionText.Replace("\r\n", "\n")));
            var fixtures = Path.Combine(Path.GetDirectoryName(Path.GetFullPath(paths.Definition))!, fixtureFile);
            if (File.Exists(fixtures)) files.Add((Path.Combine(pin, Path.GetFileName(fixtures)), File.ReadAllText(fixtures).Replace("\r\n", "\n")));
        }
        return files.Select(file => (Path.GetFullPath(file.Item1), file.Item2)).ToArray();
    }

    public static IReadOnlyList<string> Write(WireProtocolPaths paths)
    {
        var written = new List<string>();
        var encoding = new UTF8Encoding(false);
        foreach (var (path, text) in Expected(paths))
        {
            if (File.Exists(path) && File.ReadAllText(path) == text) continue;
            Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(path))!);
            var temporary = path + ".tmp";
            File.WriteAllText(temporary, text, encoding);
            File.Move(temporary, path, overwrite: true);
            written.Add(path);
        }
        return written;
    }

    /// <summary>A file's state: current, stale or missing. Line endings do not count.</summary>
    public static IReadOnlyList<WireFileState> Check(WireProtocolPaths paths) => Expected(paths).Select(file =>
        new WireFileState(file.Path, !File.Exists(file.Path) ? "missing" :
            File.ReadAllText(file.Path).Replace("\r\n", "\n") == file.Text ? "current" : "stale")).ToArray();
}
